#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "compare.h"
#include "scheduler.h"
#include "simulator.h"
#include "metrics.h"
#include "predictor.h"
#include "output.h"
static const Pc pol[]={FC,SJ,HR,LA,FQ,LO,HO,QH};
static void gn(FILE*f,const Pr*p,int n,const Tr*t,Pc pc){int i;double tm=0;fprintf(f,"\nGantt - %s\n",nm(pc));if(!t->no){fprintf(f,"(empty)\n");return;}for(i=0;i<t->no;i++){int j;const Pr*q=NULL;for(j=0;j<n;j++)if(p[j].id==t->od[i]){q=&p[j];break;}if(q){if(q->st>tm)fprintf(f,"| IDLE %.2f-%.2f ",tm,q->st);fprintf(f,"| P%d %.2f-%.2f ",q->id,q->st,q->ct);tm=q->ct;}}fprintf(f,"|\n");}
static void row(FILE*f,const Mt*m,Pc pc,double ms){fprintf(f,"%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",nm(pc),m->aw,m->at,m->ar,m->sd,m->mx,m->p5,m->p9,m->th,m->ut,ms);}
int cmp(const Pr*p,int n,const Cf*c,const char*pre,double er,int sd){char rp[512],sp[512],pp[512];FILE*rf=NULL,*csv=NULL,*pf=NULL;int i,ok=1;double fst=0;Pr*cp=NULL;Tr tr={0};Mt mt,mts[8];if(!p||n<1||!c||!pre||strlen(pre)>400||er<0||er>=1)return 0;snprintf(rp,sizeof rp,"%s_report.txt",pre);snprintf(sp,sizeof sp,"%s_summary.csv",pre);snprintf(pp,sizeof pp,"%s_processes.csv",pre);rf=fopen(rp,"w");csv=fopen(sp,"w");pf=fopen(pp,"w");if(!rf||!csv||!pf){if(rf)fclose(rf);if(csv)fclose(csv);if(pf)fclose(pf);return 0;}for(i=0;i<n;i++)if(i==0||p[i].ar<fst)fst=p[i].ar;fprintf(rf,"QH-SJF Scheduling Comparison\nProcesses: %d\nPrediction error: %.3f\nSeed: %d\n",n,er,sd);fprintf(csv,"policy,avg_wait,avg_turnaround,avg_response,avg_slowdown,max_wait,p95_wait,p99_wait,throughput,cpu_utilization_fraction,makespan\n");fprintf(pf,"policy,pid,arrival,burst,predicted,start,completion,waiting,turnaround,response,score\n");cp=malloc((size_t)n*sizeof*cp);if(!cp){fclose(rf);fclose(csv);fclose(pf);return 0;}for(i=0;i<8;i++){int j;double end=0;memcpy(cp,p,(size_t)n*sizeof*cp);pd(cp,n,er,sd);if(!sr(cp,n,pol[i],c,&tr)){ok=0;sf(&tr);break;}mt=mc(cp,n,fst,tr.tm);mts[i]=mt;for(j=0;j<n;j++)if(cp[j].ct>end)end=cp[j].ct;fprintf(rf,"\n==================================================\nPolicy: %s\n",nm(pol[i]));fprintf(rf,"Average waiting time: %.6f\nAverage turnaround time: %.6f\nAverage response time: %.6f\nAverage slowdown: %.6f\nMaximum waiting time: %.6f\nP95 waiting time: %.6f\nP99 waiting time: %.6f\nThroughput: %.6f\nCPU utilization: %.3f%%\nMakespan: %.6f\nIdle intervals: %d\n",mt.aw,mt.at,mt.ar,mt.sd,mt.mx,mt.p5,mt.p9,mt.th,mt.ut*100,end,tr.il);gn(rf,cp,n,&tr,pol[i]);row(csv,&mt,pol[i],end);for(j=0;j<n;j++)fprintf(pf,"%s,%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",nm(pol[i]),cp[j].id,cp[j].ar,cp[j].bu,cp[j].pb,cp[j].st,cp[j].ct,cp[j].wt,cp[j].tt,cp[j].rt,cp[j].sc);sf(&tr);}if(ok){int a=0,b=0,d=0,e=0;for(i=1;i<8;i++){if(mts[i].aw<mts[a].aw)a=i;if(mts[i].at<mts[b].at)b=i;if(mts[i].ar<mts[d].ar)d=i;if(mts[i].th>mts[e].th)e=i;}fprintf(rf,"\n==================================================\nComparative Highlights\nLowest average waiting time: %s (%.6f)\nLowest average turnaround time: %s (%.6f)\nLowest average response time: %s (%.6f)\nHighest throughput: %s (%.6f)\n",nm(pol[a]),mts[a].aw,nm(pol[b]),mts[b].at,nm(pol[d]),mts[d].ar,nm(pol[e]),mts[e].th);}free(cp);if(fclose(rf)!=0)ok=0;if(fclose(csv)!=0)ok=0;if(fclose(pf)!=0)ok=0;if(ok)printf("Comparison written:\n  %s\n  %s\n  %s\n",rp,sp,pp);return ok;}
/* Glossary: pol=policy list; gn=write Gantt chart; row=write summary row; cmp=compare policies; p=input workload; n=count; c=config; pre=prefix; er=prediction error; sd=seed; rp/sp/pp=report/summary/process paths; rf/sf/pf=output files; cp=working process copy; tr=simulation trace; mt=metrics; fst=first arrival; end=makespan; ok=status; i/j=loop indexes; z=size. */
